<script>
  export let authReady = false;
  export let profileLoading = false;
  export let isAdmin = false;
  export let currentRoute = 'admin/shop';
  export let adminShopLoading = false;
  export let adminShopListings = [];
  export let catalogItems = [];
  export let shopForm = {};
  export let shopAdminSaving = false;
  export let resetShopForm = () => {};
  export let editShopListing = () => {};
  export let saveShopListing = () => {};
  export let deleteShopListing = () => {};
  export let getInventoryIcon = () => '◆';
  export let isImageIcon = () => false;
</script>

{#if !authReady || profileLoading}<section class="admin-page panel"><div class="empty-state"><span>◌</span><strong>관리자 권한을 확인하는 중이에요</strong></div></section>
{:else if !isAdmin}<section class="about-page panel"><p class="eyebrow">ACCESS RESTRICTED</p><h1>관리자 권한이<br /><em>필요합니다</em></h1><p class="about-lead">이 페이지는 캠페인 관리자만 이용할 수 있습니다.</p><a class="primary-btn about-button" href="#home">홈으로 돌아가기 <span>→</span></a></section>
{:else}<section class="admin-page panel"><div class="admin-shell"><nav class="admin-sidebar" aria-label="관리자 메뉴"><div class="admin-sidebar-brand"><span class="eyebrow">CONTROL ROOM</span><strong>관리자 메뉴</strong></div><a class:active={currentRoute === 'admin'} href="#admin"><span>◌</span><span><strong>플레이어 계정 생성</strong><small>ACCOUNTS &amp; CHARACTERS</small></span></a><a href="#admin/monsters"><span>♟</span><span><strong>몬스터 관리</strong><small>MONSTER CATALOG</small></span></a><a class:active={currentRoute === 'admin/items'} href="#admin/items"><span>◇</span><span><strong>아이템 관리</strong><small>ITEM CATALOG</small></span></a><a class:active={currentRoute === 'admin/shop'} href="#admin/shop"><span>G</span><span><strong>상점 상품 관리</strong><small>SHOP INVENTORY</small></span></a><a class:active={currentRoute === 'admin/combat-test'} href="#admin/combat-test"><span>⚔</span><span><strong>전투 테스트</strong><small>CARD DRAW LAB</small></span></a><a href="#combat"><span>⚔</span><span><strong>실시간 전투방</strong><small>CO-OP CARD BATTLE</small></span></a><div class="admin-sidebar-foot">운영 도구<br /><span>CAMPAIGN ADMIN</span></div></nav><div class="admin-shell-main"><div class="page-heading"><div><p class="eyebrow">SHOP INVENTORY</p><h1>상점 상품 관리</h1><p>등록된 아이템을 상점에 진열하고 판매 상태·가격·구매 제한을 설정합니다.</p></div><a class="subtle-btn" href="#shop">상점 보기 ↗</a></div><div class="admin-shop-layout"><section class="admin-card shop-editor-card"><div class="form-section-head"><div><p class="eyebrow">{shopForm.id ? 'EDIT LISTING' : 'NEW LISTING'}</p><h2>{shopForm.id ? '판매 상품 수정' : '상점에 아이템 등록'}</h2></div>{#if shopForm.id}<button class="subtle-btn" type="button" on:click={resetShopForm}>새 상품</button>{/if}</div><form class="editor-form" on:submit|preventDefault={saveShopListing}><label>판매할 아이템<select bind:value={shopForm.item_id} disabled={Boolean(shopForm.id)} required><option value="">아이템을 선택해 주세요</option>{#each catalogItems as item}<option value={item.id}>{item.name} · {item.grade}</option>{/each}</select></label><div class="shop-form-grid"><label>가격 (G)<input bind:value={shopForm.price_g} type="number" min="0" required /><small>0으로 설정하면 무료 판매</small></label><label>개인 구매 제한<input bind:value={shopForm.personal_limit} type="number" min="1" placeholder="제한 없음" /><small>비워두면 제한 없음</small></label><label>전체 판매 수량<input bind:value={shopForm.total_limit} type="number" min="1" placeholder="제한 없음" /><small>비워두면 무제한</small></label></div><label class="shop-active-toggle"><input bind:checked={shopForm.is_active} type="checkbox" /><span><strong>현재 판매 중</strong><small>해제하면 상점에 상품은 보이지만 구매할 수 없습니다.</small></span></label>{#if shopForm.id}<div class="shop-sold-count">누적 판매 수량 <strong>{shopForm.sold_count || 0}개</strong></div>{/if}<div class="form-actions">{#if shopForm.id}<button class="subtle-btn" type="button" on:click={resetShopForm}>취소</button>{/if}<button class="primary-btn" type="submit" disabled={shopAdminSaving}>{shopAdminSaving ? '저장 중…' : shopForm.id ? '상품 수정' : '상품 등록'} <span>↗</span></button></div></form></section><section class="admin-card shop-list-card"><div class="form-section-head"><div><p class="eyebrow">SHOP INVENTORY</p><h2>등록된 판매 상품 <span class="item-count">{adminShopListings.length}</span></h2></div></div>{#if adminShopLoading}<div class="empty-state"><span>◌</span><strong>판매 상품을 불러오는 중이에요</strong></div>{:else if !adminShopListings.length}<div class="shop-empty compact"><span>◇</span><h2>등록된 상품이 없습니다</h2><p>왼쪽에서 아이템을 선택해 첫 상품을 등록해 주세요.</p></div>{:else}<div class="admin-shop-list">{#each adminShopListings as listing}<article class="admin-shop-row"><div class="shop-row-icon">{#if isImageIcon(getInventoryIcon(listing.item))}<img src={getInventoryIcon(listing.item)} alt="" />{:else}{getInventoryIcon(listing.item)}{/if}</div><div class="admin-shop-row-copy"><div><strong>{listing.item_name}</strong><span class:active-shop-status={listing.is_active && (listing.total_limit === null || listing.sold_count < listing.total_limit)} class="shop-status">{listing.total_limit !== null && listing.sold_count >= listing.total_limit ? 'SOLD OUT' : listing.is_active ? '판매 중' : '판매 준비중'}</span></div><p>{listing.price_g.toLocaleString()} G · 판매 {listing.sold_count}개{listing.total_limit === null ? '' : ` / ${listing.total_limit}개`}</p><small>1인 제한: {listing.personal_limit === null ? '없음' : `${listing.personal_limit}개`}</small></div><div class="admin-shop-row-actions"><button class="subtle-btn" type="button" on:click={() => editShopListing(listing)}>수정</button><button class="danger-btn" type="button" on:click={() => deleteShopListing(listing)}>삭제</button></div></article>{/each}</div>{/if}</section></div></div></div></section>{/if}
